import DOMPurify from 'dompurify';

interface Note {
  id: number;
  title: string;
  body: string;
  avatar: string;
  createdAt: string;
}

const STORAGE_KEY = 'porto-notes';
const ALLOWED_AVATAR_SCHEMES = ['http://', 'https://', 'data:image/'];

let notes: Note[] = [];
let nextId = 1;
let selectedNoteId: number | null = null;
let searchQuery = '';

async function loadFixtures(): Promise<Note[]> {
  const response = await fetch('/fixtures.json');
  return response.json();
}

function loadNotes(): void {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    notes = JSON.parse(stored);
    nextId = Math.max(...notes.map(n => n.id), 0) + 1;
  } else {
    loadFixtures().then(fixtures => {
      notes = fixtures;
      nextId = Math.max(...notes.map(n => n.id), 0) + 1;
      saveNotes();
      render();
    });
  }
}

function saveNotes(): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(notes));
}

function sanitizeHtml(html: string): string {
  return DOMPurify.sanitize(html, {
    ALLOWED_TAGS: ['a', 'b', 'strong', 'i', 'em', 'br'],
    ALLOWED_ATTR: ['href'],
    ALLOW_DATA_ATTR: false,
    KEEP_CONTENT: true,
  });
}

function isValidAvatarUrl(url: string): boolean {
  if (!url) return false;
  return ALLOWED_AVATAR_SCHEMES.some(scheme => url.startsWith(scheme));
}

function convertRichTextToHtml(text: string): string {
  // Convert inline tags and line breaks
  let html = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // Process tags: <b>, <strong>, <i>, <em>, <a href="...">, <br>
  html = html
    .replace(/&lt;b&gt;(.*?)&lt;\/b&gt;/g, '<b>$1</b>')
    .replace(/&lt;strong&gt;(.*?)&lt;\/strong&gt;/g, '<strong>$1</strong>')
    .replace(/&lt;i&gt;(.*?)&lt;\/i&gt;/g, '<i>$1</i>')
    .replace(/&lt;em&gt;(.*?)&lt;\/em&gt;/g, '<em>$1</em>')
    .replace(/&lt;br&gt;/g, '<br>')
    .replace(/&lt;a href=&quot;(.*?)&quot;&gt;(.*?)&lt;\/a&gt;/g, '<a href="$1">$2</a>')
    .replace(/\n/g, '<br>');

  return html;
}

function filterNotes(query: string): Note[] {
  if (!query) return notes;
  const lowerQuery = query.toLowerCase();
