import DOMPurify from 'dompurify';

interface Note {
  id: number;
  title: string;
  body: string;
  avatar: string;
  createdAt: string;
}

interface RichNode {
  type: 'text' | 'tag';
  content?: string;
  tag?: string;
  href?: string;
  children?: RichNode[];
}

const STORAGE_KEY = 'porto-notes';
const ALLOWED_AVATAR_SCHEMES = ['http://', 'https://', 'data:image/'];

let notes: Note[] = [];
let nextId = 1;
let selectedNoteId: number | null = null;
let searchQuery = '';

async function loadFixtures(): Promise<Note[]> {
  const response = await fetch('/fixtures.json');
  return response.json();
}

function loadNotes(): void {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (stored) {
    notes = JSON.parse(stored);
    nextId = Math.max(...notes.map(n => n.id), 0) + 1;
  } else {
    loadFixtures().then(fixtures => {
      notes = fixtures;
      nextId = Math.max(...notes.map(n => n.id), 0) + 1;
      saveNotes();
      render();
    });
  }
}

function saveNotes(): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(notes));
}

function isValidAvatarUrl(url: string): boolean {
  if (!url) return false;
  return ALLOWED_AVATAR_SCHEMES.some(scheme => url.startsWith(scheme));
}

function parseRichText(text: string): RichNode[] {
  const nodes: RichNode[] = [];
  let html = text;

  // Escape special characters first, but we need to unescape our tags
  html = html
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  // Unescape allowed tags and process them
  // We'll process the text and build safe nodes
  const tokens: Array<{ type: string; value: string }> = [];
  let current = '';
  let i = 0;

  while (i < html.length) {
    if (html[i] === '&' && html.substring(i, i + 4) === '&lt;') {
      if (current) tokens.push({ type: 'text', value: current });
      current = '';

      // Try to match a tag
      const tagMatch = html.substring(i).match(/^&lt;(b|strong|i|em|\/b|\/strong|\/i|\/em|br)&gt;/);
      const linkMatch = html.substring(i).match(/^&lt;a href=&quot;([^&]*)&quot;&gt;/);
      const closeLink = html.substring(i).match(/^&lt;\/a&gt;/);

      if (tagMatch) {
        const tag = tagMatch[1]!;
        tokens.push({ type: 'tag', value: tag });
        i += tagMatch[0].length;
      } else if (linkMatch) {
        const href = linkMatch[1]!;
        tokens.push({ type: 'link-start', value: href });
        i += linkMatch[0].length;
      } else if (closeLink) {
        tokens.push({ type: 'link-end', value: '' });
        i += closeLink[0].length;
      } else {
        current += html[i];
        i++;
      }
    } else {
      current += html[i];
      i++;
    }
  }

  if (current) tokens.push({ type: 'text', value: current });

  // Convert tokens to nodes using a simple stack-based parser
  const stack: any[] = [];

  for (const token of tokens) {
    if (token.type === 'text') {
      if (stack.length > 0) {
        stack[stack.length - 1].children.push({ type: 'text', content: token.value });
      } else {
        nodes.push({ type: 'text', content: token.value });
      }
    } else if (token.type === 'tag') {
      const tag = token.value;
      if (tag === 'br') {
        if (stack.length > 0) {
          stack[stack.length - 1].children.push({ type: 'tag', content: '', tag: 'br' });
        } else {
          nodes.push({ type: 'tag', content: '', tag: 'br' });
        }
      } else if (tag === 'b' || tag === 'strong' || tag === 'i' || tag === 'em') {
        const node: RichNode = { type: 'tag', tag, children: [] };
        if (stack.length > 0) {
          stack[stack.length - 1].children!.push(node);
        } else {
          nodes.push(node);
        }
        stack.push(node);
      } else if (tag === '/b' || tag === '/strong' || tag === '/i' || tag === '/em') {
        if (stack.length > 0) {
          const node = stack.pop();
          for (const child of node.children || []) {
            nodes.push(child);
          }
        }
      }
    } else if (token.type === 'link-start') {
      const node: RichNode = { type: 'tag', tag: 'a', href: token.value, children: [] };
      if (stack.length > 0) {
        stack[stack.length - 1].children!.push(node);
      } else {
        nodes.push(node);
      }
      stack.push(node);
    } else if (token.type === 'link-end') {
      if (stack.length > 0) {
        stack.pop();
      }
    }
  }

  return nodes;
}

function renderRichText(nodes: RichNode[], parent: HTMLElement): void {
  for (const node of nodes) {
    if (node.type === 'text') {
      parent.appendChild(document.createTextNode(node.content));
    } else if (node.tag === 'br') {
      parent.appendChild(document.createElement('br'));
    } else if (node.tag === 'b' || node.tag === 'strong') {
      const el = document.createElement('b');
      if ((node as any).children) {
        renderRichText((node as any).children, el);
      }
      parent.appendChild(el);
    } else if (node.tag === 'i' || node.tag === 'em') {
      const el = document.createElement('i');
      if ((node as any).children) {
        renderRichText((node as any).children, el);
      }
      parent.appendChild(el);
    } else if (node.tag === 'a' && node.href) {
      const el = document.createElement('a');
      el.href = node.href;
      el.target = '_blank';
      if ((node as any).children) {
        renderRichText((node as any).children, el);
      }
      parent.appendChild(el);
    }
  }
}

